// ─── HELPERS ──────────────────────────────────────────────────────────────────

/** Ressources visibles dans la Bibliothèque de l'élève */
export const BIBLIOTHEQUE_MEDIA = MEDIA_CATALOG.filter(
  (m) => m.visibility === 'BIBLIOTHEQUE' || m.visibility === 'BOTH',
);

/** Ressources pour un agent et/ou une œuvre donnée */
export function getMediaForAgent(
  agentType: AgentType,
  oeuvreId?: string,
): MediaEntry[] {
  return MEDIA_CATALOG.filter((m) => {
    const agentMatch =
      !m.agentTriggers ||
      m.agentTriggers.length === 0 ||
      m.agentTriggers.includes(agentType);
    const oeuvreMatch =
      !oeuvreId ||
      !m.oeuvreIds ||
      m.oeuvreIds.includes(oeuvreId);
    return agentMatch && oeuvreMatch;
  });
}

/** Formater les ressources médias en bloc texte pour injection prompt agent */
export function formatMediaContextForPrompt(entries: MediaEntry[]): string {
  if (entries.length === 0) return '';

  const lines = [
    '--- RESSOURCES MÉDIAS DISPONIBLES (internes — ne pas citer d\'URL) ---',
  ];

  for (const entry of entries.slice(0, 5)) {
    const duration = entry.durationSeconds
      ? ` (${Math.round(entry.durationSeconds / 60)} min)`
      : '';
    const typeLabel = entry.type === 'video' ? 'Vidéo' : entry.type === 'audio' ? 'Audio' : 'Document';
    lines.push(`${typeLabel} — "${entry.title}"${duration}`);
    lines.push(`  → ${entry.description}`);
    lines.push(`  → Référence interne : ${entry.sourceRef}`);
  }

  lines.push('Instruction : si une de ces ressources est pertinente, mentionne-la naturellement dans le texte par son titre exact.');
  lines.push('             Ne jamais citer une URL. Ne jamais utiliser le format [Ressource: ...] ou [Source: ...]. Intègre le titre directement dans la phrase.');

  return lines.join('\n');
}
